def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > DAILY_SALARY * 2:
                    strong_prev_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    scarcity = (25.0 - supply) / 10.0
    scarcity = max(0.0, min(1.0, scarcity))

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    elif hp <= 6:
        urgency += 0.2

    if no_water >= 2:
        urgency += 1.0
    elif no_water >= 1:
        urgency += 0.45

    if day >= 8:
        urgency += 0.15

    pressure_bid = 0.0
    if strong_prev_bids:
        pressure_bid = max(strong_prev_bids)
    elif prev_bids:
        pressure_bid = max(prev_bids)

    if pressure_bid >= 120:
        if urgency >= 1.4:
            bid = 92.0 + 10.0 * scarcity
        elif urgency >= 0.7:
            bid = 36.0 + 10.0 * scarcity
        else:
            bid = 12.0 + 6.0 * scarcity
    elif pressure_bid >= 70:
        if urgency >= 1.2:
            bid = min(88.0, pressure_bid + 2.0)
        elif urgency >= 0.5:
            bid = 48.0 + 12.0 * scarcity
        else:
            bid = 20.0 + 8.0 * scarcity
    elif pressure_bid > 0:
        target = pressure_bid + 1.25
        floor_bid = 24.0 + 18.0 * scarcity + 12.0 * urgency
        bid = max(target, floor_bid)
    else:
        bid = 22.0 + 16.0 * scarcity + 12.0 * urgency

    if supply >= 23:
        bid *= 0.72
    elif supply >= 20:
        bid *= 0.84
    elif supply <= 16:
        bid *= 1.18

    reserve = 0.0
    if hp > 4 and no_water == 0:
        reserve = DAILY_SALARY * 0.35
    elif hp > 2:
        reserve = DAILY_SALARY * 0.2

    max_affordable = max(0.0, budget - reserve)
    if urgency >= 1.5:
        max_affordable = budget

    bid = min(bid, max_affordable)

    if urgency >= 1.2:
        bid = max(bid, min(budget, 55.0 + 12.0 * scarcity))
    elif hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, 62.0))

    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = day_context['day']

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate competitive level from yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Supply pressure: with higher supply, we can bid less; with lower supply, bid more.
    supply_norm = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)  # 0..1
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base target: slightly below yesterday average/highest to exploit overbidding.
    # If others were extremely aggressive, we still need to be competitive.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        target = max(DAILY_SALARY * 0.35, avg_prev_bid * 0.88)
    else:
        target = max(DAILY_SALARY * 0.45, avg_prev_bid * 0.9)

    # My urgency: fewer hp or more consecutive no-water days -> bid up.
    if hp <= 2.0:
        target *= 1.35
    elif hp <= 4.0:
        target *= 1.15

    if no_water_days >= 2:
        target *= 1.25
    elif no_water_days == 1:
        target *= 1.10

    # Adjust with supply: lower supply means bid more.
    target *= (0.95 + (1.0 - supply_norm) * 0.25)

    # Hard caps to avoid budget ruin.
    # If budget is low, bid a fraction to preserve future rounds.
    if budget <= DAILY_SALARY * 0.6:
        cap = budget * 0.7
    elif budget <= DAILY_SALARY * 1.2:
        cap = budget * 0.55
    else:
        cap = budget * 0.45

    bid = min(cap, target)

    # Ensure non-negative and at least a small amount if needed.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_market_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 100.0

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], max(avg_market_bid * 1.1, 150.0))
    elif day_context['supply'] < 18:
        bid = min(my_status['budget'], avg_market_bid * 1.05)
    else:
        bid = min(my_status['budget'], avg_market_bid * 0.9)

    return float(max(bid, 5.0))
